(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ms"] = {"ui":{"skip":"Langkau ke kandungan","back":"← Kembali ke AI-gile","lang.button":"Bahasa: {name}","lang.dialog":"Pilih bahasa","lang.search":"Cari bahasa","lang.none":"Tiada bahasa yang sepadan","lang.notYet":"{name} belum diterjemahkan","theme.aria":"Tukar antara tema cerah dan tema gelap","theme.toLight":"Tukar ke tema cerah","theme.toDark":"Tukar ke tema gelap","words.underline":"Gariskan perkataan ini pada halaman","words.underlineHelp":"Tuding atau ketik perkataan bergaris titik untuk melihat maksudnya.","index.title":"AI-gile: pasukan pembangunan AI anda, dalam satu papan","index.description":"AI-gile ialah papan kanban untuk pasukan pengekodan AI. Mereka bekerja semasa anda tidur; anda mendapat satu longgokan pendek: apa yang perlu diputuskan, diuji dan diterima.","hero.logoAlt":"Ikon papan AI-gile","hero.h1.html":"Pasukan pembangunan AI anda, dalam satu&nbsp;papan.","hero.alpha":"🐣 Pra-alfa tertutup","hero.alphaTitle":"Masih awal dan belum siap: terima kasih kerana mencuba!","hero.lede":"Mereka membina semasa anda tidur. Anda bangun dengan satu longgokan pendek: beberapa soalan, beberapa perkara untuk diuji, satu dua berlian ungu. Klik, terima, kembali ke kopi anda.","dl.windows":"Aplikasi Windows","dl.browser":"Jalankan dalam pelayar anda","dl.soon":"Akan datang","dl.notify":"🔔 Beritahu saya bila ia dibuka","dl.notifySmall":"Alfa atau beta","hero.secondary":"Agile, tetapi pasukan ini tidak pernah perlukan kopi stand-up. (Mereka tetap buat stand-up.)","pitch.h2":"AI-gile dalam seberapa banyak perkataan yang anda mahu","pitch.lede":"Pilih panjang, dari satu perkataan hingga 144. Setiap panjang ialah penerangan tersendiri, ditulis untuk saiz itu. Seret peluncur atau guna kekunci anak panah.","pitch.rangeLabel":"Panjang dalam perkataan","pitch.dice":"🎲 versi lain","pitch.words.one":"{n} perkataan","pitch.words.other":"{n} perkataan","pitch.letters.one":"{n} huruf","pitch.letters.other":"{n} huruf","pitch.chars.one":"{n} aksara","pitch.chars.other":"{n} aksara","count.line.html.one":"{n} kad pada papan sekarang","count.line.html.other":"{n} kad pada papan sekarang","features.aria":"Apa yang ia lakukan","f.pile.h":"Satu longgokan untuk anda","f.pile.html":"<b>Untuk anda</b> mengumpulkan semua yang menunggu anda, merentas setiap projek: soalan, perkara untuk diuji, tugas yang hanya manusia boleh buat. Giliran anda memberitahu apa yang seterusnya dan berapa lama ia mengambil masa.","f.sleep.h":"Pasukan yang bekerja semasa anda tidur","f.sleep.p":"Setiap projek ada seorang ketua dan pasukan ejen AI. Beri komen pada kad dan pasukan itu bangun, menyiapkan kerja, lalu menyerahkannya semula dengan langkah yang boleh diikuti oleh manusia yang penat.","f.tester.h":"Penguji AI menyemak dahulu","f.tester.p":"Sebelum apa-apa sampai kepada anda, seorang penguji mengikut langkah dalam salinan aplikasi dan menunjukkan apa yang dilihatnya, dengan tangkapan skrin. Layari yang lulus dan terima dengan satu klik.","f.proof.h":"Bukti, bukan janji","f.proof.p":"Setiap penyerahan menunjukkan apa yang berubah: fail, perbezaan, tangkapan skrin. Tak perlu buka setiap aplikasi untuk tahu sama ada ia siap.","f.chat.h":"Berbual dengan ketua anda","f.chat.p":"Bar gaya Discord: satu ikon bagi setiap projek, berlian ungu untuk apa yang perlukan anda. Hantar idea kepada ketua; dia mengubahnya menjadi kad dan pelan, dengan butang ✅ Mula.","f.tidy.h":"Mengemas sendiri","f.tidy.p":"Kad yang berkaitan digabungkan menjadi satu, tajuk yang kusut dibetulkan, dan semakan token memastikan kod kekal ringkas. Kurang perkara untuk ditukar-tukar, kurang untuk difikirkan.","f.private.h":"Milik anda, pada komputer anda","f.private.li1":"Papan ini berjalan pada komputer anda sendiri dan hanya menjawab anda.","f.private.li2":"Mesej peribadi antara orang disulitkan hujung ke hujung.","f.private.li3":"Tiada akaun, tiada penjejak, tiada kuki.","f.lang.h":"Dalam bahasa anda","f.lang.p":"Lebih 120 bahasa, daripada Belanda, Wales dan Jepun hingga lanun, Yoda dan Klingon, dengan pertukaran pantas kembali ke bahasa Inggeris untuk perkataan pembangun.","tl.aria":"Garis masa dari perbualan pertama hingga pelan hala tuju","tl.h2":"Dari sembang pertama hingga apa yang seterusnya","tl.lede":"Tarikh dan masa sebenar, dalam zon waktu anda sendiri. Selepas hari ini ia ialah pelan, tanpa tarikh yang dijanjikan.","tl.today":"Hari ini","tl.planned":"dirancang","tl.cards.one":"{n} kad","tl.cards.other":"{n} kad","join.h2":"Sertai kami","join.lede":"AI-gile dibina oleh seorang manusia kecil dan ramai ejen yang sabar. Buat masa ini ia persendirian, dalam alfa tertutup bersama kawan-kawan. Mahu mencuba bila ia dibuka?","join.btn":"Daftar minat","join.small":"Kami akan e-mel anda, tidak lebih","footer.tag":"AI-gile. Tiada penjejak, tiada kuki, tiada kopi stand-up.","footer.licence":"Lesen perniagaan","footer.status":"Status","footer.privacy":"Apa yang kami simpan","form.sending":"Menghantar…","form.failed":"Tidak berjaya: cuba lagi nanti.","form.offline":"Tidak dapat menghubungi AI-gile: cuba lagi nanti.","form.keep":"Kami hanya menggunakan ini untuk membalas anda, kemudian memadamnya. Tiada penjejak, tiada kuki.","form.keepLink":"Apa yang kami simpan","interest.title":"AI-gile: beritahu saya bila alfa dibuka","interest.description":"Tinggalkan e-mel anda untuk tahu bila alfa atau beta tertutup AI-gile dibuka.","interest.h1":"🔔 Beritahu saya bila ia dibuka","interest.lede":"AI-gile berada dalam pra-alfa tertutup. Tinggalkan e-mel anda dan kami akan menulis sekali sahaja, apabila ada tempat untuk anda.","interest.email":"E-mel anda","interest.which":"Ujian yang mana?","interest.alpha":"Alfa tertutup: awal, kasar, banyak perubahan","interest.beta":"Beta: lebih stabil, lebih lewat","interest.both":"Mana-mana, yang datang dahulu","interest.submit":"Masukkan saya dalam senarai","interest.thanks":"Terima kasih! Anda sudah ada dalam senarai.","licence.title":"AI-gile: lesen perniagaan","licence.description":"Guna AI-gile dalam perniagaan anda? Mohon lesen perniagaan percuma.","licence.h1":"📜 Lesen perniagaan","licence.lede":"Guna AI-gile di tempat kerja? Beritahu kami siapa anda dan apa yang anda buat. Jika ia membawa kebaikan, lesen ini percuma.","licence.company":"Syarikat","licence.website":"Laman web","licence.what":"Apa yang anda buat","licence.how":"Bagaimana ia membantu dunia","licence.email":"E-mel","licence.submit":"Mohon","licence.thanks":"Terima kasih! Kami akan membalas melalui e-mel.","status.title":"Status AI-gile","status.h1":"Status AI-gile","status.quiet":"Semuanya tenang","status.intro":"Adakah AI-gile berfungsi sekarang? Halaman ini menyemak laman web, perkongsian papan, panggilan dan muat turun setiap 5 minit.","status.up":"Berfungsi (menjawab dalam {ms} ms)","status.slow":"Tidak menjawab semakan terakhir, mencuba lagi","status.down":"Terhenti: tidak menjawab dua semakan terakhir","status.svc.web":"Laman web","status.svc.web.offers":"Laman ini: apa itu AI-gile, dan borang minat","status.svc.boards":"Perkongsian papan","status.svc.boards.offers":"Papan awam, mesej antara rakan dan jemputan","status.svc.calls":"Panggilan","status.svc.calls.offers":"Suara, video dan perkongsian skrin dalam AI-gile","status.svc.download":"Muat turun","status.svc.download.offers":"Pemasang Windows dan pautan jemputan","status.checking":"Menyemak…","status.offline":"Tidak dapat menghubungi perkhidmatan status sekarang (mencuba semula)","status.updated":"dikemas kini {ago}","status.justNow":"baru sahaja","status.min":"{n} min lalu","status.hours":"{n} j lalu","status.days":"{n} h lalu","privacy.title":"AI-gile: apa yang kami simpan","privacy.h1":"Apa yang kami simpan","privacy.lede":"Ringkasnya: hanya apa yang anda hantar kepada kami, dan tidak lama.","privacy.only":"Hanya apa yang anda hantar kepada kami: apa yang anda taip dalam borang, seperti e-mel anda. Tiada apa-apa lagi tentang anda.","privacy.sealed":"Ia dimeterai supaya pelayan kami tidak dapat membacanya: dalam pelayar anda sebelum ia dihantar (pada pelayar yang lebih lama, sebaik sahaja ia tiba). Hanya papan kami sendiri yang boleh membukanya.","privacy.server":"Ia dipadam daripada pelayan sebaik sahaja ia sampai ke papan kami. Apa-apa yang masih ada di situ selepas 30 hari akan dipadam juga.","privacy.board":"Kami menyimpannya pada papan kami hanya sehingga kami membalas anda, kemudian memadamnya di situ juga.","privacy.none":"Tiada penjejak, tiada kuki, tiada analitik.","privacy.local":"Bahasa anda dan pilihan tema cerah atau gelap kekal dalam pelayar anda sendiri. Ia tidak pernah dihantar kepada kami.","privacy.ask":"Mahu ia dipadam lebih awal? Balas e-mel kami dan beritahu kami.","live.h2":"Tonton ia dibina, secara langsung","live.caption":"Setiap kad disembunyikan: anda lihat bentuk kerja, bukan perkataannya.","live.watching.one":"langsung: {n} menonton","live.watching.other":"langsung: {n} menonton","live.last.now":"Kad terakhir dialihkan sebentar tadi","live.last.min.one":"Kad terakhir dialihkan {n} minit lalu","live.last.min.other":"Kad terakhir dialihkan {n} minit lalu","live.last.hour.one":"Kad terakhir dialihkan {n} jam lalu","live.last.hour.other":"Kad terakhir dialihkan {n} jam lalu","live.last.day.one":"Kad terakhir dialihkan {n} hari lalu","live.last.day.other":"Kad terakhir dialihkan {n} hari lalu","live.offline":"Papan langsung sedang berehat sebentar. Datang lagi nanti.","live.cols":"Backlog|Untuk dibuat|Sedang dibuat|Pasukan menyemak|Untuk anda uji|Untuk pasukan|Selesai"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Diwakilkan."]},{"n":2,"texts":["Kanban robot.","Ejen, tersusun.","Idea, terbina."]},{"n":3,"texts":["Kanban untuk robot.","Idea jadi fungsi.","Kanban ejen percuma."]},{"n":5,"texts":["Papan kanban dijalankan oleh ejen.","Anda tulis kad. Ejen membina.","Percuma, setempat, teruji, agak lucu."]},{"n":8,"texts":["Papan kanban percuma tempat ejen AI bekerja.","Tulis idea. Ejen membinanya. Anda menerima.","Agile untuk seorang manusia dan ramai robot sabar."]},{"n":13,"texts":["Papan kanban pada komputer anda di mana ejen AI mengambil kad satu demi satu.","Tulis satu idea. Pasukan ejen membinanya. Seorang penguji menyemaknya dan menunjukkan hasilnya.","Tiada akaun, tiada penjejak: sebuah papan, beberapa robot, dan anda yang menentukan segalanya."]},{"n":21,"texts":["AI-gile ialah papan kanban untuk bekerja dengan ejen pengekodan AI. Mereka mengambil kad satu demi satu; anda menguji dan menerimanya.","Setiap projek ada seorang ketua dan pasukan ejen AI. Beri komen pada mana-mana kad dan pasukan itu terus mula bekerja.","Papan tugasan peribadi yang percuma dan berjalan pada komputer anda sendiri. Pekerjanya robot. Yang berkata ya ialah anda."]},{"n":34,"texts":["Anda letak idea pada papan. Pasukan ejen AI mengubahnya menjadi ciri yang berfungsi, mengujinya, dan menyerahkannya semula dengan langkah untuk dicuba. Tiada apa dikira siap sehingga anda berkata begitu.","AI-gile ialah papan kanban buatan sendiri yang dibina oleh Rich dengan banyak bantuan daripada ejen yang kini diuruskannya. Ia percuma, berjalan pada komputer anda, dan dikongsi dengan kawan, bukan dijual.","Bayangkan papan kanban biasa dengan lajur dari Backlog hingga Selesai, cuma kadnya diambil oleh ejen AI. Mereka melapor kemajuan, bertanya apabila tersangkut, dan sentiasa menunggu persetujuan anda dahulu."]},{"n":55,"texts":["AI-gile ialah papan kanban yang pasukannya terdiri daripada ejen AI. Setiap projek ada seorang ketua yang merancang kerja dan pembantu yang membinanya. Apabila sesuatu ciri siap, seorang penguji AI mencubanya dan mengambil tangkapan skrin, kemudian ia sampai ke longgokan anda. Terima, atau beri komen dan mereka mengerjakannya semula.","Ia bermula sebagai cara seorang untuk menjejak banyak sesi pengekodan AI serentak, lalu membesar menjadi papan sebenar. Ia berjalan pada mesin anda, tidak perlukan akaun, dan tiada penjejak. Ia percuma untuk kawan dan sesiapa yang ingin tahu. Ia juga belum siap, jadi jangan terkejut dengan tepi yang kasar dan kejutan sekali-sekala.","Inilah versi jujurnya. Anda masih perlu memikirkan idea, dan anda masih perlu menyemak hasilnya. AI-gile melakukan semua yang di antaranya: ia menyusun kad, membangunkan ejen yang betul apabila anda memberi komen, menunjukkan apa yang tepat berubah, dan mengumpulkan semuanya dalam satu longgokan pendek untuk anda, supaya anda tak perlu berlari antara aplikasi."]},{"n":89,"texts":["AI-gile ialah papan kanban percuma yang anda jalankan pada komputer anda sendiri. Bukannya orang, setiap projek ada pasukan ejen AI: seorang ketua yang mengubah idea anda menjadi kad dan pelan, dan pembantu yang mengambil kad mengikut keutamaan. Apabila sesuatu siap dibina, penguji AI mengikut langkah ujian dan menunjukkan apa yang dilihatnya. Kemudian ia menunggu dalam satu longgokan bernama Untuk anda. Anda menerimanya, atau beri komen dan pasukan itu mencuba lagi. Tiada apa sampai ke Selesai tanpa anda.","Beberapa perkara yang mungkin tidak anda sangka. Rondaan malam memastikan lajur Untuk dibuat sentiasa terisi semasa anda tidur, memilih kad yang tidak memerlukan jawapan daripada anda. Pembilang token menunjukkan berapa banyak yang ejen gunakan hari ini dan minggu ini, dan Mod Tanpa Token menyuruh mereka berhenti menggunakan token. Anda boleh menghantar mesej kepada kawan, dan mesej peribadi disulitkan hujung ke hujung. Papan ini bertutur dalam kira-kira 120 bahasa, termasuk Belanda, Flemish, lanun dan Klingon. Semua ini percuma, dan tiada sesiapa cuba menjualnya kepada anda.","AI-gile ialah projek peribadi yang kecil, bukan syarikat. Rich mahu menjaga beberapa projek pengekodan AI tanpa membuka setiap aplikasi untuk menyemaknya, maka dia dan ejen membina sebuah papan untuknya, kemudian menggunakan papan itu untuk membina selebihnya sendiri. Ia dalam pra-alfa tertutup, bermakna ia berfungsi, kebanyakannya, untuk segelintir kawan. Tiada halaman harga, tiada surat berita dan tiada pelan pertumbuhan. Tiada sesiapa mengumpul data anda. Jika kedengaran berguna, anda boleh minta untuk mencubanya apabila ia dibuka sedikit lagi."]},{"n":144,"texts":["AI-gile ialah papan kanban untuk seorang manusia dan ramai ejen AI. Ia berjalan pada komputer anda sendiri dan sepenuhnya percuma. Anda menambah projek, dan setiap projek mendapat seorang ketua dan pasukan kecil. Anda berbual dengan ketua, sedikit seperti Discord, dan menerangkan idea; ketua mengubahnya menjadi kad dan pelan, kemudian menunggu anda menekan Mula. Pasukan mengerjakan kad mengikut keutamaan, menggunakan barisan arahan ringkas yang dibuat untuk model bahasa. Sebelum apa-apa kembali kepada anda, penguji AI mengikut langkah dalam salinan aplikasi dan melampirkan tangkapan skrin. Kerja yang siap sampai ke longgokan anda bersama fail yang berubah dan perbezaannya. Anda menerimanya, atau meninggalkan komen dan pasukan itu bangun dan mencuba lagi. Papan ini juga mengemas sendiri: kad yang berkaitan digabungkan. Hanya anda yang boleh menggerakkan kad ke Selesai.","Begini lebih kurang sehari dengan AI-gile. Waktu petang anda tinggalkan beberapa komen: butang ini salah tempat, senarai itu patut diisih, boleh tak ada mod gelap. Anda pergi tidur. Ejen membaca komen, membuat perubahan, mengujinya dan menyerahkannya semula kepada anda. Jika Untuk dibuat kehabisan, rondaan malam mengisinya daripada backlog dengan kad yang tidak memerlukan jawapan anda. Pada waktu pagi ada satu longgokan pendek: beberapa soalan dan beberapa perkara untuk dicuba, setiap satu dengan langkah yang boleh diikuti oleh orang mengantuk dan tangkapan skrin ia berfungsi. Anda klik, terima yang baik dan hantar balik selebihnya. Jika ada yang kurang jelas, anda cuma beri komen dan ia kembali kepada pasukan. Pembilang token menunjukkan berapa banyak digunakan, dan Mod Tanpa Token ada untuk minggu yang jimat. Kemudian anda bersarapan, yang ejen belum boleh bantu.","Pertama, apa yang AI-gile bukan. Ia bukan syarikat permulaan, ia tidak dijual, dan tiada sesiapa mengumpul data anda. Ia papan percuma yang berjalan pada komputer anda, tanpa akaun, tanpa penjejak dan tanpa kuki. Apa dia: satu tempat kemas untuk melihat setiap projek pengekodan AI sekali gus, dengan pasukan ejen membuat kad dan anda membuat keputusan. Ada juga rondaan malam yang menyediakan kad semasa anda tidur. Ia menggabungkan kad yang berkaitan, membetulkan tajuk yang kusut, dan memerhati supaya kod kekal ringkas. Ia bertutur dalam kira-kira 120 bahasa, dari Belanda dan Flemish hingga lanun dan Klingon. Kawan boleh bermesej sesama sendiri, secara peribadi dan disulitkan. Ia dibina oleh Rich dan ramai ejen yang sabar, kebanyakannya menggunakan papan itu sendiri. Ia dalam pra-alfa tertutup, jadi ada bahagian yang kasar. Jika kedengaran menyeronokkan, minta dengan baik dan mungkin anda masuk awal."]}],"quips":{"1":"Satu perkataan. Berani. Mungkin terlalu berani.","3":"Tiga perkataan. Sudah lebih jujur daripada kebanyakan halaman produk.","8":"Lapan perkataan. Masih lebih pendek daripada satu stand-up.","21":"Panjang ini ialah story point, by the way. Sudah tentu.","55":"Lima puluh lima perkataan. Dua kad siap semasa anda membaca itu.","144":"Itulah yang panjang. Tiada 233. Ejen sudah pergi tidur."}},"timeline":{"first-idea.name":"Idea pertama","first-idea.line":"Perbualan paling awal, sebelum wujud sebarang kod.","first-board.name":"Papan pertama","first-board.line":"Papan yang menjejak pembinaannya sendiri: kad, lajur, seret dan lepas, projek.","team-roles.name":"Pasukan dan peranan","team-roles.line":"Profil ejen, templat pasukan, ruang dan siapa buat apa.","install.name":"Pemasangan dan keluaran","install.line":"Fail zip yang boleh dipasang oleh kawan, kemas kini sendiri, saluran dan undur semula.","usage-saver.name":"Penjimat penggunaan","usage-saver.line":"Ukur kos setiap larian, kekalkan kod ringkas, jimatkan had anda.","friends.name":"Kawan dan perkongsian","friends.line":"Mesej peribadi, geganti terenkripsi, jemputan, peranan dan projek kongsi.","languages.name":"Bahasa","languages.line":"Setiap teks skrin dalam fail bahasa, bermula dengan Belanda dan Flemish.","ai-tester.name":"Penguji AI","ai-tester.line":"Seorang penguji menyemak setiap penyerahan dahulu dan menunjukkan apa yang dilihatnya.","website.name":"Laman web","website.line":"aigile.lol, teaser dan garis masa ini.","streaming.name":"Sembang dan penstriman","streaming.line":"Discord, Twitch, OBS, mod penstrim, GIF dan emoji.","no-ai.name":"Edisi tanpa AI","no-ai.line":"Papan untuk orang yang mengekod tanpa AI, dan papan awam.","night-watch.name":"Rondaan malam","night-watch.line":"Seorang pengawal dan Scrum Master memastikan pasukan kekal pada tugas semasa anda tidur.","p-more.name":"Selebihnya","p-more.line":"Idea yang lebih kecil, masih menunggu giliran.","p-android.name":"Telefon dan Android","p-android.line":"Capai papan anda dari telefon, kemudian aplikasi Android asli.","p-release.name":"Alfa dan seterusnya","p-release.line":"Alfa tertutup, laman langsung, kemudian beta.","p-languages.name":"Lebih banyak bahasa","p-languages.line":"Lebih seratus bahasa, dan mod rendaman untuk pelajar.","p-engines.name":"Lebih banyak enjin AI","p-engines.line":"Pilih Claude, Codex atau Gemini bagi setiap ejen.","p-pro.name":"Amalan profesional","p-pro.line":"Label risiko, pintu gabungan, kad insiden dan pagar pelindung.","p-self.name":"Menjaga anda","p-self.line":"Mod penat, peringatan jaga diri dan 4:20.","p-servers.name":"Pelayan dan skala","p-servers.line":"Tetapan pelayan global, peranan dan perancangan untuk pertumbuhan.","p-livestream.name":"Tambahan penstriman","p-livestream.line":"Sembang Twitch, emoji tersuai dan paparan langsung awam."},"words":{"button":"📖 Istilah pembangun","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Cari perkataan…","none":"Tiada perkataan yang sepadan.","close":"Tutup","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Folder kod projek dan sejarah penuh commitnya, biasanya turut disimpan di GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Satu barisan kerja berasingan dalam kod, supaya perubahan boleh dibuat tanpa menyentuh versi utama.","also":["branch","cabang"]},{"id":"commit","g":"build","word":"Commit","text":"Syot kilat kod yang disimpan, dengan nota ringkas tentang apa yang berubah. Anda sentiasa boleh kembali kepadanya.","also":["commit","komit"]},{"id":"push","g":"build","word":"Push","text":"Menghantar syot kilat tersimpan (commit) dari komputer ini ke GitHub, supaya ia disandarkan dan dikongsi."},{"id":"merge","g":"build","word":"Merge","text":"Menggabungkan perubahan sebuah branch kembali ke versi utama."},{"id":"pr","g":"build","word":"Pull request","text":"Meminta perubahan sebuah branch disemak dan digabungkan ke versi utama.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Mengemaskan kod tanpa mengubah apa yang dilakukannya: fail lebih kecil, nama lebih jelas, kurang pengulangan."},{"id":"bug","g":"build","word":"Bug","text":"Sesuatu yang tidak berfungsi seperti sepatutnya.","also":["bug","pepijat"]},{"id":"test","g":"build","word":"Ujian","text":"Mencuba kerja yang sudah siap untuk memastikan ia melakukan apa yang diminta, sebelum anda menerimanya.","also":["ujian","uji","test"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Melancarkan versi baharu untuk digunakan, contohnya ke pelayan tempat orang menggunakannya."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Idea dan kerja yang belum dirancang. Tiada apa di situ dikerjakan sehingga dialihkan ke Untuk dibuat."},{"id":"sprint","g":"team","word":"Sprint","text":"Tempoh kerja yang singkat (selalunya seminggu atau dua) dengan set kad yang dipersetujui untuk disiapkan.","also":["sprint"]},{"id":"standup","g":"team","word":"Stand-up","text":"Semakan pantas: apa yang setiap ahli pasukan telah buat, apa yang mereka buat seterusnya, dan apa yang menghalang mereka.","also":["standup","stand-up"]},{"id":"kanban","g":"team","word":"Kanban","text":"Papan berlajur (Untuk dibuat, Sedang dibuat, Selesai) tempat kad bergerak dari kiri ke kanan seiring kerja berjalan."},{"id":"wip","g":"team","word":"Had WIP","text":"Work in progress: bilangan kad paling banyak yang patut ada dalam sesebuah lajur, supaya pasukan menyiapkan sesuatu sebelum memulakan yang lain.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Ejen","text":"AI yang bekerja sendiri pada sesuatu tugas: membaca kod, membuat perubahan, menjalankan semakan, dan melapor balik.","also":["ejen","agent"]},{"id":"token","g":"team","word":"Token","text":"Unit untuk mengira penggunaan AI: lebih kurang beberapa huruf teks yang dibaca atau ditulis. Makin sedikit token, makin banyak baki pelan anda.","also":["token","tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Arahan kecil yang berjalan sendiri pada saat tertentu, cth. apabila sesi AI bermula, supaya pasukan mendengar komen anda.","also":["hook","hooks"]}]}};
